def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    parents = list(map(int, data[1:n+1]))
    m = int(data[n+1])
    queries = [(int(data[n+2 + 2*i]), int(data[n+3 + 2*i])) for i in range(m)]

    # Build the tree
    tree = defaultdict(list)
    for i in range(1, n+1):
        if parents[i-1] != 0:
            tree[parents[i-1]].append(i)

    # Precompute ancestors
    max_p = max(p for _, p in queries)
    ancestors = [[0] * (max_p + 1) for _ in range(n + 1)]

    def bfs(start):
        queue = deque([(start, 0)])
        while queue:
            node, depth = queue.popleft()
            if depth < max_p:
                for child in tree[node]:
                    ancestors[child][depth + 1] = node
                    queue.append((child, depth + 1))

    for i in range(1, n+1):
        if parents[i-1] == 0:
            bfs(i)

    # Answer the queries
    results = []
    for v, p in queries:
        if p == 0:
            results.append(0)
        else:
            common_ancestor = v
            for _ in range(p):
                common_ancestor = ancestors[common_ancestor][1]
            if common_ancestor == 0:
                results.append(0)
            else:
                count = 0
                for child in tree[common_ancestor]:
                    if child != v:
                        count += 1
                results.append(count)

    print(' '.join(map(str, results)))

